div.script:
document.addEventListener('DOMContentLoaded', function() {
    // Helper para modales de Bootstrap
    function showModal(el) {
        if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
            var m = bootstrap.Modal.getInstance(el) || new bootstrap.Modal(el);
            m.show();
        } else if (typeof jQuery !== 'undefined') {
            jQuery(el).modal('show');
        }
    }

    // Editar vehículo
    document.querySelectorAll('.btn-edit-vehiculo').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            var modal = document.getElementById('modalAddVehiculo');
            modal.querySelector('[name="vehiculo_id"]').value = this.dataset.id || '';
            modal.querySelector('[name="placa"]').value = this.dataset.placa || '';
            modal.querySelector('[name="marca_id"]').value = this.dataset.marca || '';
            modal.querySelector('[name="modelo"]').value = this.dataset.modelo || '';
            modal.querySelector('[name="anio"]').value = this.dataset.anio || '2020';
            modal.querySelector('[name="color"]').value = this.dataset.color || '';
            modal.querySelector('.modal-title').innerHTML = ' Editar Vehículo';
            showModal(modal);
        });
    });

    // Eliminar vehículo
    document.querySelectorAll('.btn-delete-vehiculo').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            document.getElementById('deleteVehiculoNombre').textContent = this.dataset.nombre;
            document.getElementById('deleteVehiculoLink').href = '/taller/vehiculo/delete/' + this.dataset.id;
            showModal(document.getElementById('modalDeleteVehiculo'));
        });
    });

    // Reset modal al abrir para crear nuevo
    var addBtn = document.querySelector('[data-bs-target="#modalAddVehiculo"]');
    if (addBtn) {
        addBtn.addEventListener('click', function(e) {
            var modal = document.getElementById('modalAddVehiculo');
            modal.querySelector('[name="vehiculo_id"]').value = '';
            modal.querySelector('form').reset();
            modal.querySelector('.modal-title').innerHTML = ' Añadir Vehículo';
        });
    }

    // ----------------- WIZARD CITA MODAL -----------------
    const stepsCita = [
        document.getElementById('step1-cita'),
        document.getElementById('step2-cita')
    ];
    const indicatorsCita = [
        document.getElementById('ind-step1-cita'),
        document.getElementById('ind-step2-cita')
    ];
    const progressCita = document.getElementById('wizard-progress-cita');
    const errorBoxCita = document.getElementById('error-message-cita');

    const vehiculoSelectCita = document.getElementById('vehiculo_select_cita');
    const nuevoVehiculoFieldsCita = document.getElementById('nuevo-vehiculo-fields-cita');
    const requiredVehFieldsCita = document.querySelectorAll('.required-veh-field-cita');

    // Lógica para mostrar/ocultar campos de nuevo vehículo
    function toggleNuevoVehiculoCita() {
        if (!vehiculoSelectCita || vehiculoSelectCita.value === 'new') {
            if (nuevoVehiculoFieldsCita) {
                nuevoVehiculoFieldsCita.classList.remove('d-none');
            }
            requiredVehFieldsCita.forEach(f => f.classList.add('required-step1-cita'));
        } else {
            if (nuevoVehiculoFieldsCita) {
                nuevoVehiculoFieldsCita.classList.add('d-none');
            }
            requiredVehFieldsCita.forEach(f => {
                f.classList.remove('required-step1-cita');
                f.classList.remove('is-invalid');
            });
        }
    }

    if (vehiculoSelectCita) {
        vehiculoSelectCita.addEventListener('change', toggleNuevoVehiculoCita);
    }
    toggleNuevoVehiculoCita(); // Ejecución inicial

    function updateUICita(stepIndex) {
        stepsCita.forEach(s => { if(s) s.classList.add('d-none'); });
        if (stepsCita[stepIndex - 1]) stepsCita[stepIndex - 1].classList.remove('d-none');

        indicatorsCita.forEach((ind, i) => {
            if (!ind) return;
            if(i < stepIndex) {
                ind.classList.replace('bg-light', 'bg-primary');
                ind.classList.replace('text-muted', 'text-white');
                ind.classList.remove('border');
            } else {
                ind.classList.replace('bg-primary', 'bg-light');
                ind.classList.replace('text-white', 'text-muted');
                ind.classList.add('border');
            }
        });

        if (progressCita) progressCita.style.width = ((stepIndex - 1) * 100) + '%';
        if (errorBoxCita) errorBoxCita.classList.add('d-none');
    }

    function validateStepCita(stepIndex) {
        let isValid = true;
        const fields = document.querySelectorAll('.required-step' + stepIndex + '-cita');
        fields.forEach(f => {
            if(!f.value.trim()) {
                isValid = false;
                f.classList.add('is-invalid');
            } else {
                f.classList.remove('is-invalid');
            }
        });
        return isValid;
    }

    // Botones Siguiente
    document.querySelectorAll('.btn-next-cita').forEach(btn => {
        btn.addEventListener('click', function() {
            let currentStep = parseInt(this.getAttribute('data-step'));
            if(validateStepCita(currentStep)) {
                updateUICita(currentStep + 1);
            } else {
                errorBoxCita.textContent = 'Por favor, completa todos los campos requeridos.';
                errorBoxCita.classList.remove('d-none');
            }
        });
    });

    // Botones Atrás
    document.querySelectorAll('.btn-prev-cita').forEach(btn => {
        btn.addEventListener('click', function() {
            let currentStep = parseInt(this.getAttribute('data-step'));
            updateUICita(currentStep - 1);
        });
    });

    // ===== WEEKLY SLOTS GRID =====
    const weeklyGrid = document.getElementById('weekly_slots_grid');
    const hiddenDateInput = document.getElementById('date_cita');
    const weekLabel = document.getElementById('week-range-label');
    let currentWeekStart = null;

    function getMonday(d) {
        const date = new Date(d);
        const day = date.getDay();
        const diff = date.getDate() - day + (day === 0 ? -6 : 1);
        return new Date(date.setDate(diff));
    }

    function formatDateISO(d) {
        return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    }

    async function loadWeekSlots(weekStartStr) {
        weeklyGrid.innerHTML = '<div class="text-center text-muted py-4"><i class="fa fa-spinner fa-spin fa-2x mb-2"></i><p class="small">Cargando horarios...</p></div>';
        hiddenDateInput.value = '';

        try {
            const params = {};
            if (weekStartStr) params.week_start = weekStartStr;

            const response = await fetch('/taller/cita/get_week_slots', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params })
            });

            const data = await response.json();
            if (!data.result || !data.result.success) {
                weeklyGrid.innerHTML = '<div class="text-danger text-center py-3"><i class="fa fa-exclamation-triangle me-1"></i> Error al cargar horarios.</div>';
                return;
            }

            const result = data.result;
            currentWeekStart = result.week_start;
            weekLabel.textContent = result.week_start + '  →  ' + result.week_end;

            const days = result.days;
            if (!days || days.length === 0) {
                weeklyGrid.innerHTML = '<div class="text-muted text-center py-3">No hay días disponibles esta semana.</div>';
                return;
            }

            // Build table
            let html = '<table class="table table-bordered text-center mb-0" style="min-width: 600px;">';
            html += '<thead><tr>';
            days.forEach(day => {
                html += '<th class="bg-primary text-white small fw-bold py-2" style="font-size: 0.85rem;">' + day.label + '</th>';
            });
            html += '</tr></thead><tbody>';

            // Find max slots across days
            let maxSlots = 0;
            days.forEach(day => { if (day.slots.length > maxSlots) maxSlots = day.slots.length; });

            for (let r = 0; r < maxSlots; r++) {
                html += '<tr>';
                days.forEach(day => {
                    if (r < day.slots.length) {
                        const slot = day.slots[r];
                        const radioId = 'slot_' + day.date + '_' + slot.hour;
                        const val = day.date + 'T' + slot.time;
                        if (slot.available) {
                            html += '<td class="py-1 px-1 slot-cell-available" style="cursor:pointer;" data-val="' + val + '">';
                            html += '<label class="d-flex align-items-center justify-content-center gap-1 mb-0 small" style="cursor:pointer;" for="' + radioId + '">';
                            html += '<input type="radio" name="slot_radio" id="' + radioId + '" value="' + val + '" class="slot-radio" style="accent-color: #0d6efd;"/> ';
                            html += slot.time + '</label></td>';
                        } else {
                            html += '<td class="py-1 px-1 text-muted" style="opacity:0.4; text-decoration: line-through;">';
                            html += '<span class="small">' + slot.time + '</span></td>';
                        }
                    } else {
                        html += '<td></td>';
                    }
                });
                html += '</tr>';
            }

            html += '</tbody></table>';
            weeklyGrid.innerHTML = html;

            // Attach radio change events
            weeklyGrid.querySelectorAll('.slot-radio').forEach(radio => {
                radio.addEventListener('change', function() {
                    hiddenDateInput.value = this.value;
                    hiddenDateInput.classList.remove('is-invalid');
                    // Highlight selected row cell
                    weeklyGrid.querySelectorAll('.slot-cell-available').forEach(td => {
                        td.style.backgroundColor = '';
                    });
                    this.closest('td').style.backgroundColor = '#e7f1ff';
                });
            });

            // Click on cell to select radio
            weeklyGrid.querySelectorAll('.slot-cell-available').forEach(td => {
                td.addEventListener('click', function(e) {
                    if (e.target.tagName !== 'INPUT') {
                        const radio = this.querySelector('.slot-radio');
                        if (radio) { radio.checked = true; radio.dispatchEvent(new Event('change')); }
                    }
                });
            });

        } catch (e) {
            console.error(e);
            weeklyGrid.innerHTML = '<div class="text-danger text-center py-3"><i class="fa fa-exclamation-triangle me-1"></i> Error de conexión.</div>';
        }
    }

    // Week navigation
    document.getElementById('btn-prev-week').addEventListener('click', function() {
        if (currentWeekStart) {
            const d = new Date(currentWeekStart + 'T00:00:00');
            d.setDate(d.getDate() - 7);
            loadWeekSlots(formatDateISO(d));
        }
    });
    document.getElementById('btn-next-week').addEventListener('click', function() {
        if (currentWeekStart) {
            const d = new Date(currentWeekStart + 'T00:00:00');
            d.setDate(d.getDate() + 7);
            loadWeekSlots(formatDateISO(d));
        }
    });

    // Load initial week when step 2 is shown
    const origUpdateUI = updateUICita;
    updateUICita = function(stepIndex) {
        origUpdateUI(stepIndex);
        if (stepIndex === 2 && !currentWeekStart) {
            loadWeekSlots(null);
        }
    };

    // Enviar form y Validar AJAX
    const btnSubmitCita = document.getElementById('btn-submit-wizard-cita');
    if (btnSubmitCita) {
        btnSubmitCita.addEventListener('click', async function() {
            if(!hiddenDateInput.value) {
                errorBoxCita.textContent = 'Por favor, selecciona un horario de la grilla.';
                errorBoxCita.classList.remove('d-none');
                return;
            }

            btnSubmitCita.disabled = true;
            btnSubmitCita.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i> Verificando...';

            const dateVal = hiddenDateInput.value;

            try {
                const response = await fetch('/taller/cita/check_availability', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        jsonrpc: "2.0",
                        method: "call",
                        params: { date: dateVal }
                    })
                });

                const data = await response.json();
                const result = data.result;

                if (result && result.available) {
                    document.getElementById('cita-wizard-form').submit();
                } else {
                    errorBoxCita.textContent = result ? result.message : 'Error al verificar disponibilidad.';
                    errorBoxCita.classList.remove('d-none');
                    btnSubmitCita.disabled = false;
                    btnSubmitCita.innerHTML = '<i class="fa fa-check-circle me-2"></i> SOLICITAR CITA';
                }
            } catch (err) {
                console.error(err);
                errorBoxCita.textContent = 'Error de conexión. Intente nuevamente.';
                errorBoxCita.classList.remove('d-none');
                btnSubmitCita.disabled = false;
                btnSubmitCita.innerHTML = '<i class="fa fa-check-circle me-2"></i> SOLICITAR CITA';
            }
        });
    }

    // Auto-abrir modal si hay error en la URL
    var urlParamsCita = new URLSearchParams(window.location.search);
    if (urlParamsCita.has('error_cita')) {
        showModal(document.getElementById('modalAddCita'));
    }

    // Reset modal al cerrar/abrir
    document.querySelectorAll('[data-bs-target="#modalAddCita"]').forEach(btn => {
        btn.addEventListener('click', function() {
            updateUICita(1);
            currentWeekStart = null;
            var form = document.getElementById('cita-wizard-form');
            if (form) form.reset();
            toggleNuevoVehiculoCita();
        });
    });
});

document.addEventListener("DOMContentLoaded", function() {
    // Ocultar notificaciones automáticamente después de 4 segundos
    setTimeout(function() {
        const alerts = document.querySelectorAll('.alert-dismissible');
        alerts.forEach(function(alert) {
            alert.style.transition = "opacity 0.5s ease";
            alert.style.opacity = "0";
            setTimeout(() => alert.remove(), 500);
        });
    }, 4000);

    // Limpiar los parámetros GET de la URL
    if (window.history.replaceState) {
        const url = new URL(window.location);
        const paramsToRemove = [
            'success_cita', 'error_cita', 'success_foto', 'error_foto', 
            'success_pass', 'error_pass', 'success_profile', 'error_profile', 'error'
        ];
        let removed = false;
        paramsToRemove.forEach(param => {
            if (url.searchParams.has(param)) {
                url.searchParams.delete(param);
                removed = true;
            }
        });
        if (removed) {
            window.history.replaceState(null, null, url.pathname + url.search);
        }
    }
});
